begin;
create function pg_temp.care_assert(ok boolean,label text) returns text language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;return label;end $$;
create function pg_temp.care_denied(stmt text,label text,expected text default '42501') returns text language plpgsql as $$begin begin execute stmt;exception when others then if sqlstate<>expected then raise exception 'Wrong error % for %',sqlstate,label;end if;return label;end;raise exception 'Unexpected success: %',label;end $$;
create temporary table inform_fixture(name text primary key,value jsonb);grant select,insert,update on inform_fixture to authenticated,service_role;
insert into inform_fixture values('period',jsonb_build_object('start',(date_trunc('week',now() at time zone 'America/Santiago')::date-7)::text));
create function pg_temp.ip()returns jsonb language sql as $$select jsonb_build_object('kind','weekly','start_day',value->>'start')from inform_fixture where name='period'$$;
create function pg_temp.ir()returns uuid language sql as $$select (value#>>'{}')::uuid from inform_fixture where name='report'$$;
insert into auth.users(id,email) select ('e1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'informs-sql-qa-'||n||'@example.test' from generate_series(1,8)n;
insert into public.admin_users(user_id,role,is_active)select ('e1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,case when n=8 then 'editor'::public.admin_role else 'viewer'::public.admin_role end,true from generate_series(3,8)n;
insert into public.patient_profiles(id,auth_user_id,email,display_name)select ('e2000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('e1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'informs-sql-qa-'||n||'@example.test','Persona informe QA '||n from generate_series(1,2)n;
insert into public.care_staff_capabilities(user_id,capabilities)select ('e1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,array['care.directory.read','care.patient.read','care.records.read','care.records.create','care.family.read']||case when n in(6,7)then array['care.decisions.manage','care.reports.export']else array[]::text[]end from generate_series(3,7)n;
insert into public.care_assignments(patient_id,professional_id,specialty,starts_at,created_by)select 'e2000000-0000-4000-8000-000000000001',('e1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,case n when 3 then 'psychology' when 4 then 'recovery' else 'direction'end,now()-interval '2 years','e1000000-0000-4000-8000-000000000006' from generate_series(3,7)n;
insert into public.care_assignments(patient_id,professional_id,specialty,starts_at,created_by)values('e2000000-0000-4000-8000-000000000002','e1000000-0000-4000-8000-000000000006','direction',now()-interval '2 years','e1000000-0000-4000-8000-000000000006');
insert into public.care_events(id,title,kind,starts_at,ends_at,professional_id,modality,status,closed_at,created_by)select ('e3000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'Sesión informe neutral '||n,case n when 1 then 'individual' when 2 then 'recovery' when 3 then 'family' else 'sport'end,
 ((pg_temp.ip()->>'start_day')::date+1)::timestamp at time zone 'America/Santiago'+interval '10 hours',((pg_temp.ip()->>'start_day')::date+1)::timestamp at time zone 'America/Santiago'+interval '11 hours',
 ('e1000000-0000-4000-8000-'||lpad((case n when 1 then 3 else 4 end)::text,12,'0'))::uuid,'in_person',case when n=4 then 'cancelled'else 'completed'end,now()-interval '1 hour','e1000000-0000-4000-8000-000000000006' from generate_series(1,4)n;
insert into public.care_event_participants(event_id,patient_id,attendance)select id,'e2000000-0000-4000-8000-000000000001',case when kind='individual'then 'present'else 'absent'end from public.care_events where id::text like 'e3000000-%';
insert into public.care_session_records(id,patient_id,event_id,author_id,specialty,occurred_at,status,revision,first_finalized_at)select 'e4000000-0000-4000-8000-000000000001','e2000000-0000-4000-8000-000000000001',id,professional_id,'psychology',starts_at,'final',1,now() from public.care_events where id='e3000000-0000-4000-8000-000000000001';
insert into private.care_record_versions(id,record_id,revision,occurred_at,payload,reason,actor_id)select 'e5000000-0000-4000-8000-000000000001',id,1,occurred_at,'{"objective":"Objetivo autorizado QA","evolution":"stable","facts":"Hechos registrados QA","difficulties":"Dificultad registrada QA"}','Original QA',author_id from public.care_session_records where id='e4000000-0000-4000-8000-000000000001';
insert into private.care_record_reserves values('e5000000-0000-4000-8000-000000000001','RESERVA EXCLUIDA INFORME QA');
insert into public.care_report_rules(id,kind,effective_on,opens_local,closes_local,close_next_day,basis,weekdays,fields,required_fields,approved_by,reason)values('e6000000-0000-4000-8000-000000000001','morning','2020-01-01','08:00','11:00',false,'active_days',array[1,2,3,4,5,6,7],array['state'],array['state'],'e1000000-0000-4000-8000-000000000006','Regla QA neutral');
insert into public.care_report_obligations(id,patient_id,local_day,kind,rule_id,opens_at,closes_at,fields,required_fields,required,requirement_reason,generated_at)select ('e7000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'e2000000-0000-4000-8000-000000000001',(pg_temp.ip()->>'start_day')::date+n,'morning','e6000000-0000-4000-8000-000000000001',((pg_temp.ip()->>'start_day')::date+n)::timestamp at time zone 'America/Santiago'+interval '8 hours',((pg_temp.ip()->>'start_day')::date+n)::timestamp at time zone 'America/Santiago'+interval '11 hours',array['state'],array['state'],true,'Obligación QA',((pg_temp.ip()->>'start_day')::date+n)::timestamp at time zone 'America/Santiago'+interval '8 hours' from generate_series(1,2)n;
insert into public.care_daily_reports(id,patient_id,author_id,answers,first_submitted_at)select id,patient_id,'e1000000-0000-4000-8000-000000000001','{"state":"Estado referido QA"}',closes_at from public.care_report_obligations where id='e7000000-0000-4000-8000-000000000001';
set local role anon;
select pg_temp.care_denied($$select public.care_inform_list()$$,'Anonymous cannot list reports');
select pg_temp.care_denied($$select public.care_inform_write('generate',pg_temp.ip())$$,'Anonymous cannot generate reports');
reset role;set local role authenticated;
select set_config('request.jwt.claim.sub','e1000000-0000-4000-8000-000000000001',true);
select pg_temp.care_denied($$select public.care_inform_write('generate',pg_temp.ip())$$,'Patient cannot generate internal report');
select set_config('request.jwt.claim.sub','e1000000-0000-4000-8000-000000000008',true);
select pg_temp.care_denied($$select public.care_inform_list()$$,'CMS alone cannot read internal reports');
select set_config('request.jwt.claim.sub','e1000000-0000-4000-8000-000000000003',true);
select pg_temp.care_denied($$select public.care_inform_write('generate',pg_temp.ip())$$,'Assigned professional needs export capability');
select set_config('request.jwt.claim.sub','e1000000-0000-4000-8000-000000000006',true);
select pg_temp.care_denied($$select public.care_inform_write('generate',pg_temp.ip()||'{"patient_id":"e2000000-0000-4000-8000-000000000099"}')$$,'Foreign patient cannot enter report');
select pg_temp.care_denied($$select public.care_inform_write('generate',pg_temp.ip()||'{"kind":"arbitrary"}')$$,'No arbitrary period','P0001');
select pg_temp.care_denied($$select public.care_inform_write('generate',pg_temp.ip()||jsonb_build_object('start_day',(date_trunc('week',now() at time zone 'America/Santiago')::date)::text))$$,'Open week rejected','P0001');
select pg_temp.care_denied($$select public.care_inform_write('generate',pg_temp.ip()||jsonb_build_object('start_day',((pg_temp.ip()->>'start_day')::date+1)::text))$$,'Week starts on Monday','P0001');
select pg_temp.care_denied($$select public.care_inform_write('generate',pg_temp.ip()||'{"start_day":"2020-01-06"}')$$,'Bounded past periods','P0001');
insert into inform_fixture values('report',to_jsonb(public.care_inform_write('generate',pg_temp.ip())));
insert into inform_fixture values('monthly',to_jsonb(public.care_inform_write('generate',jsonb_build_object('kind','monthly','start_day','2026-04-01','patient_id','e2000000-0000-4000-8000-000000000002'))));
select pg_temp.care_assert(extract(epoch from((public.care_inform_read((select (value#>>'{}')::uuid from inform_fixture where name='monthly'))->'inform'->>'end_at')::timestamptz-(public.care_inform_read((select (value#>>'{}')::uuid from inform_fixture where name='monthly'))->'inform'->>'start_at')::timestamptz))=721*3600,'Generated month uses actual DST bounds');
select pg_temp.care_assert(public.care_inform_read((select (value#>>'{}')::uuid from inform_fixture where name='monthly'))->'snapshot'->>'source_total'='0','Empty monthly individual does not invent sources');
select pg_temp.care_assert(public.care_inform_write('generate',pg_temp.ip())=pg_temp.ir(),'Repeated generation returns same report');
select pg_temp.care_assert(public.care_inform_read(pg_temp.ir())->'inform'->>'revision'='1','Idempotence does not duplicate version');
select pg_temp.care_assert(public.care_inform_read(pg_temp.ir())->'snapshot'->>'population'='2','Population unique authorized patients');
select pg_temp.care_assert(jsonb_array_length(public.care_inform_read(pg_temp.ir())->'snapshot'->'needs_review')=1,'Only patient with documented pending sources enters review list');
select pg_temp.care_assert(public.care_inform_read(pg_temp.ir())->'version'->>'state'='generated','Generated is pending explicit review');
select pg_temp.care_assert((select sum((r->>'n')::int)=2 from jsonb_array_elements(public.care_inform_read(pg_temp.ir())->'snapshot'->'counts')r where r->>'metric'='attendance'),'Canceled and family not ordinary attendance');
select pg_temp.care_assert((select sum((r->>'n')::int)=3 from jsonb_array_elements(public.care_inform_read(pg_temp.ir())->'snapshot'->'counts')r where r->>'metric'='records'),'Family expected even patient absent');
select pg_temp.care_assert((select (r->>'n')::int=1 from jsonb_array_elements(public.care_inform_read(pg_temp.ir())->'snapshot'->'counts')r where r->>'metric'='reports' and r->>'category'='on_time'),'Equality at deadline is on time');
select pg_temp.care_assert((select (r->>'n')::int=1 from jsonb_array_elements(public.care_inform_read(pg_temp.ir())->'snapshot'->'counts')r where r->>'metric'='reports' and r->>'category'='omitted'),'Only generated required obligation omitted');
select pg_temp.care_assert(public.care_inform_read(pg_temp.ir())->'snapshot'->'quality'->>'without_obligations'='1','Missing obligations distinct from omission');
select pg_temp.care_assert(public.care_inform_read(pg_temp.ir())->'snapshot'->'quality'->>'scheduler_verified'='false','No scheduler falsely certified');
select pg_temp.care_assert(public.care_inform_read(pg_temp.ir())::text not like '%RESERVA EXCLUIDA%','Reserved text excluded from entire snapshot');
select pg_temp.care_assert(public.care_inform_read(pg_temp.ir())::text like '%Estado referido QA%','Autodeclaration copied with its source');
select pg_temp.care_denied($$select * from private.care_informs$$,'No direct private table access');
select pg_temp.care_denied($$select private.care_inform_snapshot(array['e2000000-0000-4000-8000-000000000002']::uuid[],now()-interval '1 year',now(),now())$$,'Internal source helper not callable');
select pg_temp.care_denied($$select public.care_inform_pdf_finish(gen_random_uuid(),gen_random_uuid(),true,100,repeat('a',64))$$,'Normal JWT cannot forge PDF readiness');
select pg_temp.care_denied($$select public.care_inform_read(pg_temp.ir(),99)$$,'Foreign revision rejected');
select pg_temp.care_denied($$select public.care_inform_read(pg_temp.ir(),null,0)$$,'Invalid source page rejected','P0001');
select pg_temp.care_denied($$select public.care_inform_write('review',jsonb_build_object('id',pg_temp.ir(),'version',1,'reason','Revisión QA'))$$,'Review requires deliberate confirmation','P0001');
select public.care_inform_write('review',jsonb_build_object('id',pg_temp.ir(),'version',1,'reason','Fuentes revisadas QA','confirm_review',true,'reviewed_by','e1000000-0000-4000-8000-000000000001'));
select pg_temp.care_assert(public.care_inform_read(pg_temp.ir())->'version'->>'reviewed_by'='e1000000-0000-4000-8000-000000000006','Reviewer derived from Auth not client');
select pg_temp.care_assert(public.care_inform_read(pg_temp.ir(),1)->'version'->>'state'='generated','Original unreviewed version preserved');
select pg_temp.care_assert(public.care_inform_read(pg_temp.ir())->'version'->>'state'='reviewed','Review creates own frozen version');
select pg_temp.care_denied($$select public.care_inform_write('regenerate',jsonb_build_object('id',pg_temp.ir(),'version',1,'reason','Nueva fuente QA'))$$,'Stale revision rejected','40001');
reset role;
insert into private.care_record_versions(record_id,revision,occurred_at,payload,reason,actor_id)select id,2,occurred_at,'{"objective":"Objetivo enmendado QA","evolution":"improved","facts":"Hechos actualizados QA"}','Enmienda QA',author_id from public.care_session_records where id='e4000000-0000-4000-8000-000000000001';
update public.care_session_records set revision=2 where id='e4000000-0000-4000-8000-000000000001';
set local role authenticated;
select public.care_inform_write('regenerate',jsonb_build_object('id',pg_temp.ir(),'version',2,'reason','Incorporar enmienda QA'));
select pg_temp.care_assert(public.care_inform_read(pg_temp.ir(),1)::text like '%Objetivo autorizado QA%','Old narrative cannot be overwritten by amendment');
select pg_temp.care_assert(public.care_inform_read(pg_temp.ir())::text like '%Objetivo enmendado QA%','Regeneration incorporates known amendment');
select pg_temp.care_assert(public.care_inform_read(pg_temp.ir())->'version'->>'state'='generated','Regeneration resets review without changing past state');
insert into inform_fixture values('pdf',public.care_inform_pdf_begin(pg_temp.ir(),1));
select pg_temp.care_denied($$select public.care_inform_pdf_begin(pg_temp.ir(),1)$$,'Concurrent pending export rejected','55P03');
select pg_temp.care_denied($$select public.care_inform_download(pg_temp.ir(),1)$$,'Pending export cannot be downloaded');
reset role;
insert into storage.objects(bucket_id,name,metadata)select 'care-informs',value->>'object_key','{"size":150,"mimetype":"application/pdf"}'from inform_fixture where name='pdf';
set local role service_role;
select pg_temp.care_denied($$select public.care_inform_pdf_finish((select (value->>'id')::uuid from inform_fixture where name='pdf'),(select (value->>'token')::uuid from inform_fixture where name='pdf'),true,151,repeat('a',64))$$,'Size mismatch cannot finalize actual Storage metadata','P0001');
select pg_temp.care_denied($$select public.care_inform_pdf_finish((select (value->>'id')::uuid from inform_fixture where name='pdf'),gen_random_uuid(),true,150,repeat('a',64))$$,'Wrong export lease rejected','P0001');
select public.care_inform_pdf_finish((select (value->>'id')::uuid from inform_fixture where name='pdf'),(select (value->>'token')::uuid from inform_fixture where name='pdf'),true,150,repeat('a',64));
