insert into public.care_assignments(patient_id,professional_id,specialty,starts_at,created_by)values('e2000000-0000-4000-8000-000000000002','e1000000-0000-4000-8000-000000000007','direction',now()-interval '2 years','e1000000-0000-4000-8000-000000000006');
