select pg_temp.care_denied($$select public.care_inform_write('regenerate',jsonb_build_object('id',pg_temp.ir(),'version',3,'reason','Regeneración ajena QA'))$$,'Regeneration restricted to original generator');
reset role;
update public.care_staff_capabilities set capabilities=array_remove(capabilities,'care.family.read')where user_id='e1000000-0000-4000-8000-000000000006';
set local role authenticated;select set_config('request.jwt.claim.sub','e1000000-0000-4000-8000-000000000006',true);
select pg_temp.care_denied($$select public.care_inform_read(pg_temp.ir(),1)$$,'Family capability revocation invalidates historical report');
select pg_temp.care_denied($$select public.care_inform_download(pg_temp.ir(),1)$$,'Revocation invalidates ready old PDF');
