set local role authenticated;
select pg_temp.care_denied($$select public.care_inform_read(pg_temp.ir())$$,'One revoked assignment blocks whole frozen report');
reset role;
update public.care_assignments set ends_at=null where professional_id='e1000000-0000-4000-8000-000000000006';
