select pg_temp.care_assert(not public.care_inform_pdf_finish((select (value->>'id')::uuid from inform_fixture where name='retry-pdf'),(select (value->>'token')::uuid from inform_fixture where name='retry-pdf'),true,150,repeat('a',64)),'Revoked actor cannot finalize even with valid server lease');
