insert into private.care_delegated_tasks(id,decision_id,patient_id,assignee_id,instruction,created_by,created_at)values('e9000000-0000-4000-8000-000000000001','e8000000-0000-4000-8000-000000000001','e2000000-0000-4000-8000-000000000001','e1000000-0000-4000-8000-000000000003','Instrucción mínima propia QA','e1000000-0000-4000-8000-000000000007',(pg_temp.ip()->>'start_day')::date+interval '2 days');
