select pg_temp.care_assert(not (select public from storage.buckets where id='care-informs'),'Report bucket private');
select pg_temp.care_assert((select count(*)=3 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='private'and c.relname in('care_informs','care_inform_versions','care_inform_exports')and c.relrowsecurity),'All new private tables have RLS');
select pg_temp.care_assert((select count(*)=0 from private.care_audit where resource_id=pg_temp.ir() and action like '%QA%'),'Audit excludes report text');
